vec3 dots = clamp01(.03/length(uv1));
ret1 = (-ret1 / 4.0) + 5.0*dots*(-0.08+ret1);
vec3 blurry1 = GetBlur3(uv) * 2.0;
vec3 ret2 = texture(sampler_dust1, (uv * 1.0*uTexSize.xy + uFrame)*texsize_dust1.zw).xyz;
//ret = ret1;
ret = abs(ret1-0.2*blurry1) * 2.0;
//ret = mix(abs(ret1-0.2*blurry1) * 2.0,abs(ret2 - 0.3*blurry1),0.1);
}
  fragColor = vec4(ret, 1.0);
}

